<template><div class="milkdown" @paste.prevent="onPaste"><textarea v-model="text" @input="onInput" aria-label="编辑笔记"></textarea><img v-for="url in imageUrls" :key="url" :src="url" alt=""></div></template><script setup lang="ts">import {ref,watch,computed} from 'vue';import {useNotesStore} from '../stores/notes';import {apiUpload} from '../api/client';const props=defineProps<{noteId:string;content:string}>();const notes=useNotesStore();const text=ref(props.content);const imageUrls=computed(()=>[...text.value.matchAll(/!\[[^\]]*\]\((\/api\/images\/[^)]+)\)/g)].map(m=>m[1]));watch(()=>props.content,v=>{if(v!==text.value)text.value=v});let timer:number|undefined;function schedule(){window.clearTimeout(timer);timer=window.setTimeout(()=>notes.saveBody(props.noteId,text.value),800)}function onInput(){schedule()}async function onPaste(e:ClipboardEvent){const file=e.clipboardData?.files?.[0];if(!file||!file.type.startsWith('image/')){const plain=e.clipboardData?.getData('text/plain');if(plain){text.value+=plain;schedule()}return}try{const r=await apiUpload(file,props.noteId);text.value+=`\n![](${r.url})\n`;schedule()}catch{window.dispatchEvent(new CustomEvent('snotes:image-error'))}}</script>
